/** Terminates tracked clients and waits for server sockets to close before stopping each server. */
export async function drainEngines(
  trackedClients: WebSocket[],
  trackedServers: Array<Pick<HalServer, 'wss' | 'stop'>>
): Promise<void> {
  for (const client of trackedClients.splice(0)) client.terminate();
  for (const hal of trackedServers.splice(0)) {
    const {wss} = hal;
    await eventually(() => wss.clients.size === 0);
    await hal.stop();
  }
}

/** Polls a condition until it holds or ~500 ms elapse. */
export async function eventually(check: () => boolean): Promise<void> {
  for (let attempt = 0; attempt < 50 && !check(); attempt++) await new Promise(resolve => setTimeout(resolve, 10));
}

/** Wraps a store with only the five required SessionStore members so optional ones can be omitted or overridden. */
