function validatePingMessage(message: Record<string, unknown>): ValidationResult {
  if (typeof message.timestamp !== 'number') {
    return {valid: false, error: 'ping must have timestamp number'};
  }

  return {
    valid: true,
    data: {
      type: 'ping',
      timestamp: message.timestamp,
    },
  };
}

function validateListSessionsMessage(message: Record<string, unknown>): ValidationResult {
  const limit = parseListLimit(message.limit);
  if (limit === null) {
    return {valid: false, error: 'list_sessions limit must be a non-negative integer'};
  }

  const before = parseListCursor(message.before);
  if (before === null) {
    return {valid: false, error: 'list_sessions before must have a valid sessionId and updatedAt'};
  }

  const validated: ListSessionsMessage = {type: 'list_sessions'};
  if (limit !== undefined) validated.limit = limit;
  if (before !== undefined) validated.before = before;
  return {valid: true, data: validated};
}

function parseListLimit(rawLimit: unknown): number | undefined | null {
  if (rawLimit === undefined) return undefined;
  if (typeof rawLimit !== 'number') return null;
  if (!Number.isInteger(rawLimit) || rawLimit < 0) return null;
  return rawLimit;
}

function parseListCursor(rawBefore: unknown): SessionCursor | undefined | null {
  if (rawBefore === undefined) return undefined;
  if (typeof rawBefore !== 'object' || rawBefore === null || Array.isArray(rawBefore)) return null;

  const cursor = rawBefore as Record<string, unknown>;
  if (!isValidCursorSessionId(cursor.sessionId)) return null;
  if (!isValidCursorTimestamp(cursor.updatedAt)) return null;

  return {sessionId: cursor.sessionId, updatedAt: cursor.updatedAt};
}

function isValidCursorSessionId(sessionId: unknown): sessionId is string {
  if (typeof sessionId !== 'string') return false;
  return sessionId.length >= 1 && sessionId.length <= MAX_SESSION_ID_LENGTH;
}

function isValidCursorTimestamp(updatedAt: unknown): updatedAt is string | number {
  if (typeof updatedAt !== 'string' && typeof updatedAt !== 'number') return false;
  return Number.isFinite(new Date(updatedAt).getTime());
}

